parameters.functionCode:
const deals = $input.all().map(i => i.json);
if (!deals.length || !deals[0].deal_id) return [{ json: { no_data: true } }];

const firstTouch = {}; // Source gets 100% credit
const lastTouch = {};  // Last touchpoint gets 100%
const linear = {};     // Equal credit across all touchpoints
const timeDecay = {};  // More recent = more credit

let totalRevenue = 0;

for (const deal of deals) {
  const value = parseFloat(deal.deal_value) || 0;
  totalRevenue += value;
  const touchpoints = deal.touchpoints || [];

  if (touchpoints.length === 0) continue;

  // First Touch
  const firstSource = deal.first_touch_source || 'direct';
  firstTouch[firstSource] = (firstTouch[firstSource] || 0) + value;

  // Last Touch
  const lastTp = touchpoints[touchpoints.length - 1];
  const lastSource = lastTp?.data?.source || lastTp?.type || 'unknown';
  lastTouch[lastSource] = (lastTouch[lastSource] || 0) + value;

  // Linear
  const creditPerTouch = value / touchpoints.length;
  for (const tp of touchpoints) {
    const source = tp.data?.source || tp.type || 'unknown';
    linear[source] = (linear[source] || 0) + creditPerTouch;
  }

  // Time Decay (half-life = 7 days)
  const dealClosed = new Date(deal.deal_closed).getTime();
  let totalWeight = 0;
  const weights = touchpoints.map(tp => {
    const tpTime = new Date(tp.at).getTime();
    const daysBeforeClose = (dealClosed - tpTime) / (1000 * 60 * 60 * 24);
    const weight = Math.pow(0.5, daysBeforeClose / 7);
    totalWeight += weight;
    return { tp, weight };
  });

  for (const { tp, weight } of weights) {
    const source = tp.data?.source || tp.type || 'unknown';
    const credit = (weight / totalWeight) * value;
    timeDecay[source] = (timeDecay[source] || 0) + credit;
  }
}

// Format results
const formatModel = (model) => Object.entries(model)
  .map(([source, value]) => ({ source, revenue: Math.round(value), percent: Math.round(value / totalRevenue * 100) }))
  .sort((a, b) => b.revenue - a.revenue)
  .slice(0, 10);

return [{
  json: {
    period: new Date(Date.now() - 30*24*60*60*1000).toLocaleString('id-ID', { month: 'long', year: 'numeric' }),
    total_conversions: deals.length,
    total_revenue: totalRevenue,
    models: {
      first_touch: formatModel(firstTouch),
      last_touch: formatModel(lastTouch),
      linear: formatModel(linear),
      time_decay: formatModel(timeDecay)
    },
    recommended_model: 'time_decay',
    generated_at: new Date().toISOString()
  }
}];

